/*
 * wubu_walkthrough.c -- the first-run walkthrough, with the official art.
 *
 * getting_started.c is a document you read. This is the walkthrough you
 * CLICK: four steps, each with a pose from the clipart pack, real buttons
 * (Back / Next / Finish), and a step indicator. It teaches the desktop by
 * pointing at the thing it describes.
 *
 * The poses are baked RGBA tables (wubu_walkthrough_art.h) generated by
 * tools/mascot_encode.py -- the WM needs no image decoder.
 *
 * C11, opaque API, no god headers.
 */
#include "../gui/wm.h"
#include "../gui/shell/window_chrome.h"
#include "../kernel/vbe.h"
#include "wubu_walkthrough_art.h"

#include <stdio.h>
#include <string.h>

#define WALK_STEP_TITLE_H 20
#define WALK_BODY_MAX     6
#define WALK_BTN_W        84
#define WALK_BTN_H        24
#define WALK_PAD          14

typedef struct {
    const char *title;
    const char *body[WALK_BODY_MAX];
    const unsigned char *art;
} WalkStep;

/* The steps are the real path: the terminal exists, HolyD exists, the VWS
 * designer exists, and the buddy is the AGI gateway. Nothing aspirational. */
static const WalkStep STEPS[] = {
  { "Welcome to WuBuOS",
    { "A from-scratch C11 operating system: its own kernel, shell,",
      "compiler and GUI framework. Everything on this desktop was built",
      "by the OS from its own source.",
      "",
      "This is a five-step walkthrough. Press Next to begin." },
    WALK_POSE_STUDY },
  { "Your first program",
    { "Open the HolyC Terminal from the launcher, then type:",
      "",
      "    holyd hello.hc",
      "",
      "HolyD is the C compiler built into the tree. Or write a GUI app in",
      "Lua -- save it as hello.wet and open it with the .wet launcher." },
    WALK_POSE_READ },
  { "Design a window, visually",
    { "Programs > Development > VWS Designer opens the form designer.",
      "Drag a control onto the form, click it, edit its properties, pick",
      "an event, write the handler, and press Save.",
      "",
      "The designer is written in Lua over .WET -- the same framework it",
      "designs for." },
    WALK_POSE_HERO },
  { "Where things live",
    { "src/kernel      the kernel",
      "src/gui/wet     the .WET widget framework",
      "src/gui/vws     the VWS form designer",
      "src/gui/wua     the Lua interpreter (Wua)",
      "src/compiler    HolyD / HolyC",
      "src/apps        the built-in applications" },
    WALK_POSE_READ },
  { "Meet WuBu",
    { "The little fellow in the corner is WuBu, the desktop buddy.",
      "Click him and the AGI HolyC terminal opens -- the ring-0 REPL",
      "where the Brain is hosted in the Body.",
      "",
      "He is also the friendly face of the agentic workflow: the MCP",
      "server lets an agent see and act through this desktop." },
    WALK_POSE_COOK },
};
#define WALK_STEPS ((int)(sizeof(STEPS) / sizeof(STEPS[0])))

#define WALK_MAX_W 640
#define WALK_H    470

static int g_step;
static int g_last_result;      /* set by the host: 0 = still walking */
static ChromeContentRect g_rect;   /* content rect from the last draw */

static void walk_draw(DosGuiWindow *win, uint32_t *fb, int fb_w, int fb_h) {
    ChromeContentRect c = chrome_draw_window(win, fb, fb_w, fb_h);
    if (!win) return;
    g_rect = c;

    const WalkStep *s = &STEPS[g_step];
    int y = c.y + WALK_PAD;

    /* Title. */
    vbe_draw_text(c.x + WALK_PAD, y, s->title, 0x000080, 2);
    y += WALK_STEP_TITLE_H;

    /* Rule under the title. */
    vbe_fill_rect(c.x + WALK_PAD, y, c.w - WALK_PAD * 2, 1, 0x808080);
    y += 6;

    /* The pose, on the left; the body wraps beside it. */
    int art_x = c.x + WALK_PAD;
    int art_y = y;
    for (int dy = 0; dy < WALK_POSE_SIZE; dy++) {
        for (int dx = 0; dx < WALK_POSE_SIZE; dx++) {
            const unsigned char *px = s->art + (dy * WALK_POSE_SIZE + dx) * 4;
            int a = px[3];
            if (a == 0) continue;
            int sx = art_x + dx, sy = art_y + dy;
            if (sx < c.x || sx >= c.x + c.w || sy < c.y || sy >= c.y + c.h) continue;
            uint32_t dst = fb[sy * fb_w + sx];
            uint32_t dr = (dst >> 16) & 0xFF, dg = (dst >> 8) & 0xFF, db = dst & 0xFF;
            uint32_t inv = (uint32_t)(255 - a);
            uint32_t rr = ((uint32_t)px[0] * a + dr * inv) / 255u;
            uint32_t gg = ((uint32_t)px[1] * a + dg * inv) / 255u;
            uint32_t bb = ((uint32_t)px[2] * a + db * inv) / 255u;
            fb[sy * fb_w + sx] = 0xFF000000u | (rr << 16) | (gg << 8) | bb;
        }
    }

    /* Body text, wrapped to the right of the art (or full width on the
     * last step where the text is long). */
    int tx = art_x + WALK_POSE_SIZE + WALK_PAD;
    int tw = (c.x + c.w - WALK_PAD) - tx;
    if (tw < 160) { tx = c.x + WALK_PAD; tw = c.w - WALK_PAD * 2; }
    int ty = y;
    for (int i = 0; i < WALK_BODY_MAX && s->body[i]; i++) {
        if (s->body[i][0] == '\0') { ty += 6; continue; }
        vbe_draw_text(tx, ty, s->body[i], 0x000000, 1);
        ty += 14;
    }

    /* Step indicator dots. */
    int dots_w = WALK_STEPS * 14;
    int dx0 = c.x + (c.w - dots_w) / 2;
    int dy0 = c.y + c.h - WALK_BTN_H - 18;
    for (int i = 0; i < WALK_STEPS; i++) {
        uint32_t col = (i == g_step) ? 0x000080 : 0xC0C0C0;
        vbe_fill_rect(dx0 + i * 14, dy0, 8, 8, col);
    }

    /* Buttons. */
    int by = c.y + c.h - WALK_BTN_H - 6;
    int bx_next = c.x + c.w - WALK_PAD - WALK_BTN_W;
    int bx_back = bx_next - WALK_BTN_W - 8;

    bool last = (g_step == WALK_STEPS - 1);
    const char *next_label = last ? "Finish" : "Next";

    /* Back */
    vbe_fill_rect(bx_back, by, WALK_BTN_W, WALK_BTN_H, 0xC0C0C0);
    vbe_rect_rounded(bx_back, by, WALK_BTN_W, WALK_BTN_H, 3, 0x404040);
    vbe_draw_text(bx_back + 18, by + 7, "Back", 0x000000, 1);

    /* Next / Finish -- the default action gets the bright face. */
    vbe_fill_rect(bx_next, by, WALK_BTN_W, WALK_BTN_H, last ? 0x007000 : 0x000080);
    vbe_rect_rounded(bx_next, by, WALK_BTN_W, WALK_BTN_H, 3, 0x404040);
    vbe_draw_text(bx_next + (last ? 14 : 20), by + 7, next_label, 0xFFFFFF, 1);
}

static void walk_key(DosGuiWindow *win, uint32_t key, uint32_t mods) {
    (void)mods;
    switch (key) {
    case 27: /* Esc */
        g_last_result = 1;
        wm_destroy(win);
        break;
    case 30: /* up   */
        if (g_step > 0) g_step--;
        break;
    case 31: /* down */
        if (g_step < WALK_STEPS - 1) g_step++;
        break;
    default: break;
    }
}

static void walk_mouse(DosGuiWindow *win, int x, int y, int btn, int kind) {
    if (kind != 1) return;
    ChromeContentRect c = g_rect;
    int by = c.y + c.h - WALK_BTN_H - 6;
    int bx_next = c.x + c.w - WALK_PAD - WALK_BTN_W;
    int bx_back = bx_next - WALK_BTN_W - 8;

    if (y < by || y > by + WALK_BTN_H) return;

    bool last = (g_step == WALK_STEPS - 1);
    if (x >= bx_next && x <= bx_next + WALK_BTN_W) {
        if (last) { g_last_result = 1; wm_destroy(win); }
        else g_step++;
    } else if (x >= bx_back && x <= bx_back + WALK_BTN_W) {
        if (g_step > 0) g_step--;
    }
}

/* Open the walkthrough. Returns 1 when the user finished it, 0 if the
 * window could not be created. */
int wubu_walkthrough_run(void) {
    g_step = 0;
    g_last_result = 0;

    DosGuiWindow *win = wm_create(80, 60, WALK_MAX_W, WALK_H,
                                 "Getting Started - WuBuOS");
    if (!win) return 0;
    win->on_draw  = walk_draw;
    win->on_key   = walk_key;
    win->on_mouse = walk_mouse;
    return 1;
}

/* Number of steps, for hosts that want to render their own chrome. */
int wubu_walkthrough_steps(void) { return WALK_STEPS; }
